UPDATE public.site_pages SET eyebrow = replace(eyebrow,'CarnageMC','WardenMC'), highlight = replace(highlight,'CarnageMC','WardenMC'), intro = replace(intro,'CarnageMC','WardenMC'), seo_description = replace(seo_description,'CarnageMC','WardenMC'), sections = replace(sections::text,'CarnageMC','WardenMC')::jsonb WHERE concat_ws(' ',eyebrow,highlight,intro,seo_description,sections::text) LIKE '%CarnageMC%';
UPDATE public.features SET title = replace(title,'CarnageMC','WardenMC'), description = replace(description,'CarnageMC','WardenMC'), long_description = replace(long_description,'CarnageMC','WardenMC') WHERE concat_ws(' ',title,description,long_description) LIKE '%CarnageMC%';
UPDATE public.game_modes SET name = replace(name,'CarnageMC','WardenMC'), tagline = replace(tagline,'CarnageMC','WardenMC'), description = replace(description,'CarnageMC','WardenMC'), long_description = replace(long_description,'CarnageMC','WardenMC') WHERE concat_ws(' ',name,tagline,description,long_description) LIKE '%CarnageMC%';
UPDATE public.changelog_entries SET title = replace(title,'CarnageMC','WardenMC'), content = replace(content,'CarnageMC','WardenMC') WHERE concat_ws(' ',title,content) LIKE '%CarnageMC%';
UPDATE public.site_content SET value = jsonb_set(value,'{message}',to_jsonb(replace(value->>'message','CarnageMC','WardenMC'))) WHERE key = 'maintenance' AND value->>'message' LIKE '%CarnageMC%';
UPDATE public.site_content SET value = jsonb_set(value,'{welcomeMessage}',to_jsonb(replace(value->>'welcomeMessage','CarnageMC','WardenMC'))) WHERE key = 'discord_bot' AND value->>'welcomeMessage' LIKE '%CarnageMC%';
UPDATE public.site_content SET value = jsonb_set(value,'{services}',(SELECT jsonb_agg(CASE WHEN service->>'key' = 'minecraft' THEN jsonb_set(service,'{desc}',to_jsonb('play.warden.rip'::text)) ELSE service END ORDER BY ord) FROM jsonb_array_elements(value->'services') WITH ORDINALITY AS s(service,ord))) WHERE key = 'status_page' AND value->'services' @> '[{"key":"minecraft","desc":"mc.CarnageMC.net"}]'::jsonb;